(function(){
  var P = AutoJS.players()[0];
  var L = AutoJS.level();
  var ME = Java.loadClass('com.merlinkitsune.astral_dice.effect.ModEffects');
  var Eff = Java.loadClass('com.merlinkitsune.astral_dice.platform.util.Effects');
  var MEI = Java.loadClass('net.minecraft.world.effect.MobEffectInstance');
  AutoJS.command('kill @e[type=!player,distance=..48]');
  AutoJS.command('clear @a');
  AutoJS.command('effect clear @a');
  var x = P.getX(), y = P.getY(), z = P.getZ();
  var z1 = AutoJS.summon('minecraft:zombie', x + 3.0, y, z);
  var z2 = AutoJS.summon('minecraft:zombie', x + 5.0, y, z);
  z1.setNoAi(true);
  z2.setNoAi(true);
  var out = {};
  out.z1MaxHealth = z1.getMaxHealth();
  out.z2MaxHealth = z2.getMaxHealth();
  var h1 = z1.getHealth();
  z1.hurt(L.damageSources().magic(), 10.0);
  out.dmgNoMark = h1 - z1.getHealth();
  z2.addEffect(new MEI(Eff.holder(ME.WEAK_MARK.get()), 600, 0));
  out.z2HasWeakMark = z2.hasEffect(Eff.holder(ME.WEAK_MARK.get()));
  var h2 = z2.getHealth();
  z2.hurt(L.damageSources().magic(), 10.0);
  out.dmgWithWeakMark = h2 - z2.getHealth();
  out.z1Health = z1.getHealth();
  out.z2Health = z2.getHealth();
  return out;
})()

